// ── EDIT THIS CONFIG ONCE ─────────────────────────────────
const CONFIG = {
  telegramChatId: '-1001234567890',   // ops group chat id
  adminEmail: 'ops@mediportbd.com',
  fromEmail: 'no-reply@mediportbd.com',
  highValueThreshold: 50000,          // BDT
};
// ──────────────────────────────────────────────────────────
const d = ($input.item.json.body && $input.item.json.body.data !== undefined ? $input.item.json.body.data : $input.item.json.data) || {};
return {
  json: {
    CONFIG,
    orderNumber: d.orderNumber,
    totalAmount: d.totalAmount || 0,
    subtotal: d.subtotal || 0,
    paymentMethod: d.paymentMethod,
    itemCount: d.itemCount,
    isB2BOrder: !!d.isB2BOrder,
    customerName: d.customer?.name || d.deliveryAddress?.name || 'Guest',
    customerPhone: d.customer?.phone || d.deliveryAddress?.phone || '-',
    items: d.items || [],
    eventId: ($input.item.json.body && $input.item.json.body.eventId !== undefined ? $input.item.json.body.eventId : $input.item.json.eventId)
  }
};

const o = $input.item.json;
const lines = o.items.map(i => `• ${i.name} (${i.sku}) ×${i.qty} — ৳${(i.price * i.qty).toLocaleString()}`).join('\n');
const telegramText = [
  `<b>🛒 NEW ORDER #${o.orderNumber}</b>`,
  ``,
  `👤 ${o.customerName} (${o.customerPhone})`,
  `💳 ${o.paymentMethod.toUpperCase()}${o.isB2BOrder ? ' • B2B' : ''}`,
  `📦 ${o.itemCount} item(s)`,
  `💰 <b>৳${o.totalAmount.toLocaleString()}</b>`,
  ``,
  lines
].join('\n');
const html = `
  <h2>New Order #${o.orderNumber}</h2>
  <p><b>Customer:</b> ${o.customerName} (${o.customerPhone})<br/>
     <b>Payment:</b> ${o.paymentMethod.toUpperCase()}<br/>
     <b>Total:</b> ৳${o.totalAmount.toLocaleString()}</p>
  <table border="1" cellpadding="6" style="border-collapse:collapse">
    <tr><th>Product</th><th>SKU</th><th>Qty</th><th>Line Total</th></tr>
    ${o.items.map(i => `<tr><td>${i.name}</td><td>${i.sku}</td><td>${i.qty}</td><td>৳${(i.price * i.qty).toLocaleString()}</td></tr>`).join('')}
  </table>`;
return { json: { ...o, telegramText, html } };
